import "server-only";

import path from "node:path";
import { STORAGE_ROOT } from "@/server/config/storage-paths";
import { resolveWithinStorage } from "./atomic";
import { LIBRARY_INVALID_ERROR } from "./contract";

const EXPORTS_DIRECTORY = "EXPORTS";
const BACKUP_NAME = /^library-[0-9A-Za-z.-]{1,80}\.(?:tar\.gz|manifest\.json)$/;

/**
 * Backup paths live in `EXPORTS/` at the storage root. Names are generated by
 * the export route; this module is the single place that proves a name cannot
 * leave that folder.
 */
export function exportsDirectory(): string {
    return resolveWithinStorage(path.join(STORAGE_ROOT, EXPORTS_DIRECTORY));
}

export function resolveExportFile(name: string): string {
    if (typeof name !== "string" || name.includes("..") || !BACKUP_NAME.test(name)) {
        throw new Error(LIBRARY_INVALID_ERROR);
    }
    const directory = exportsDirectory();
    const candidate = path.resolve(directory, name);
    if (path.dirname(candidate) !== directory) throw new Error(LIBRARY_INVALID_ERROR);
    return candidate;
}
